-- Run in the Neon database connected to Render. Student role only.
BEGIN;
CREATE TEMP TABLE requested_student_access(roll_number text PRIMARY KEY) ON COMMIT DROP;
SELECT s.user_id,'student' FROM students s JOIN requested_student_access r USING(roll_number)
JOIN users u ON u.id=s.user_id WHERE u.active
ON CONFLICT(user_id,role) DO NOTHING;
SELECT r.roll_number,u.full_name,
 CASE WHEN s.id IS NULL THEN 'NOT_REGISTERED' WHEN NOT u.active THEN 'DISABLED_ACCOUNT'
 WHEN ur.user_id IS NOT NULL THEN 'STUDENT_ACCESS_GRANTED' ELSE 'NEEDS_REVIEW' END AS access_status
FROM requested_student_access r LEFT JOIN students s USING(roll_number)
LEFT JOIN users u ON u.id=s.user_id
LEFT JOIN user_roles ur ON ur.user_id=s.user_id AND ur.role='student'
ORDER BY r.roll_number;
COMMIT;

